const phraseMap = new Map(phraseRows.map(row => [row[0], row]));
const originalNodes = [];
const translatedPlaceholders = [...document.querySelectorAll('[data-i18n-placeholder]')];
const translatedAttributes = [...document.querySelectorAll('[aria-label], img[alt]')].flatMap(element =>
  ['aria-label', 'alt'].filter(attribute => element.hasAttribute(attribute)).map(attribute => ({ element, attribute, key: element.getAttribute(attribute) }))
);

const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (walker.nextNode()) {
  const node = walker.currentNode;
  const parent = node.parentElement;
  const value = node.nodeValue.trim();
  if (!value || !parent || parent.closest('#language-menu') || parent.closest('#language-button') || parent.closest('[data-i18n-skip]')) continue;
  originalNodes.push({ node, raw: node.nodeValue, key: value });
}

let currentLocale = 'hi';

function translate(key, locale = currentLocale) {
  const row = phraseMap.get(key);
  const index = localeOrder.indexOf(locale);
  return row && index >= 0 ? row[index] : key;
}

function applyLocale(locale) {
  if (!localeOrder.includes(locale)) locale = 'hi';
  currentLocale = locale;
  document.documentElement.lang = locale;

  originalNodes.forEach(({ node, raw, key }) => {
    node.nodeValue = raw.replace(key, translate(key, locale));
  });

  translatedPlaceholders.forEach(element => {
    element.setAttribute('placeholder', translate(element.dataset.i18nPlaceholder, locale));
  });

  translatedAttributes.forEach(({ element, attribute, key }) => {
    element.setAttribute(attribute, translate(key, locale));
  });

  document.querySelectorAll('[data-language-button]').forEach(languageButton => {
    languageButton.childNodes[0].nodeValue = `${localeMeta[locale].name} `;
    languageButton.setAttribute('aria-label', `Language: ${localeMeta[locale].name}`);
  });

  document.querySelectorAll('#language-menu [data-lang]').forEach(button => {
    const isSelected = button.dataset.lang === locale;
    button.classList.toggle('selected-language', isSelected);
    button.querySelector('.language-check').textContent = isSelected ? '✓' : '';
    button.setAttribute('aria-pressed', String(isSelected));
  });

  try { localStorage.setItem('shilpsarathi-language', locale); } catch (_) {}
  window.dispatchEvent(new CustomEvent('languagechange', { detail: { locale } }));
}

window.I18N = {
  apply: applyLocale,
  t: translate,
  languageName(locale = currentLocale) { return localeMeta[locale]?.name || localeMeta.hi.name; },
  get locale() { return currentLocale; }
};
